// Collect all valid leads from Output 0 into a single array
const validLeads = $input.all().map((item, index) => ({
  lead_id: index + 1,
  email: item.json.email,
  first_name: item.json.first_name,
  company_name: item.json.company_name,
  job_title: item.json.job_title,
  tool_input: item.json.tool_input,
  tool_output: item.json.tool_output
}));

// Return as a single item wrapping the array
return [{ json: { leads_array: validLeads } }];

const seenEmails = new Set();

for (const item of $input.all()) {
  const email = (item.json.email || '').toLowerCase().trim();
  const jobTitle = (item.json.job_title || '').toLowerCase().trim();
  const toolInput = (item.json.tool_input || '').toLowerCase().trim();
  const firstName = (item.json.first_name || '').toLowerCase().trim();

  let status = 'Valid';
  let rejection_reason = '';

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  // 1. Basic Email Format Check
  if (!emailRegex.test(email)) {
    status = 'Rejected';
    rejection_reason = 'Invalid email address format';
  } 
  // 2. Check for Duplicates in Batch
  else if (seenEmails.has(email)) {
    status = 'Rejected';
    rejection_reason = 'Duplicate submission within dataset';
  }
  // 3. Filter Incomplete / Null Data
  else if (
    !toolInput || 
    toolInput === 'null' || 
    toolInput.trim() === '' ||
    !item.json.tool_output || 
    item.json.tool_output === 'null'
  ) {
    status = 'Rejected';
    rejection_reason = 'Incomplete submission (missing tool input or output)';
  }
  // 4. Filter Test Entries
  else if (
    email.includes('test@') || 
    email.includes('asdf') || 
    toolInput === 'test' || 
    toolInput.includes('12345') || 
    firstName === 'test'
  ) {
    status = 'Rejected';
    rejection_reason = 'Test entry with placeholder data';
  } 
  // 5. Filter Non-Buyers
  else if (
    jobTitle.includes('open to work') ||
    jobTitle.includes('student') || 
    jobTitle.includes('intern') || 
    jobTitle.includes('seeking job') || 
    toolInput.includes('homework') || 
    toolInput.includes('zero budget')
  ) {
    status = 'Rejected';
    rejection_reason = 'Non-buyer profile (student/academic/no budget)';
  } else {
    seenEmails.add(email);
  }

  item.json.cleaned_status = status;
  item.json.rejection_reason = rejection_reason;
}

return $input.all();

// Extract raw response from Gemini
const item = $input.first().json;

let rawText = 
  item.content?.parts?.[0]?.text ||
  item.candidates?.[0]?.content?.parts?.[0]?.text ||
  item.text ||
  '';

// Clean out markdown wrapper fences
rawText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();

try {
  const parsedLeads = JSON.parse(rawText);

  // DEDUPLICATION: Ensure only one entry per email per batch
  const uniqueLeadsMap = new Map();
  for (const lead of parsedLeads) {
    if (lead && lead.email) {
      uniqueLeadsMap.set(lead.email.toLowerCase().trim(), lead);
    }
  }
  const uniqueLeads = Array.from(uniqueLeadsMap.values());

  const processedItems = uniqueLeads.map(lead => {
    let emailText = lead.generated_email;

    if (emailText && typeof emailText === 'string') {
      emailText = emailText.split('\\n').join('\n');
      emailText = emailText.replace(/\ban 100/gi, 'a 100');
    }

    let status, route, routingDestination, reviewStatus, rejectionReason;

    // Three-tier classification logic based on your score
    if (lead.score >= 8) {
      status = "Hot";
      route = "active_outreach_alert";
      routingDestination = "active_outreach_pipeline";
      reviewStatus = "auto_approved";
      rejectionReason = null;
    } else if (lead.score >= 5) {
      status = "Warm";
      route = "nurture_sequence";
      routingDestination = "nurture_pipeline";
      reviewStatus = "auto_approved";
      rejectionReason = null;
    } else {
      status = "Not a fit";
      route = "human_review_queue";
      routingDestination = "human_review_queue";
      reviewStatus = "pending_human_approval";
      rejectionReason = lead.score_reason || "Low commercial alignment or non-buyer profile.";
      emailText = null; 
    }

    // Helper to derive clean names and company names from email/ID if missing
    const emailStr = lead.email || "";
    let derivedName = lead.full_name || emailStr.split("@")[0] || "Unknown";
    derivedName = derivedName.charAt(0).toUpperCase() + derivedName.slice(1).replace(".", " ");

    let derivedCompany = lead.company_name || "";
    if (!derivedCompany && emailStr.includes("@")) {
      const domain = emailStr.split("@")[1];
      if (domain && !domain.includes("gmail")) {
        const compPart = domain.split(".")[0];
        derivedCompany = compPart.charAt(0).toUpperCase() + compPart.slice(1);
      } else {
        derivedCompany = "Independent / Self";
      }
    }

    return {
      json: {
        raw_lead_id: lead.lead_id ? lead.lead_id.toString() : null,
        email: lead.email,
        full_name: derivedName,
        company_name: derivedCompany,
        status: status,
        rejection_reason: rejectionReason,
        fit_score: lead.score,
        score_reason: lead.score_reason,
        matched_service: lead.matched_service,
        route: route,
        generated_email: emailText,
        company_size: lead.company_size || null,
        funding_stage: lead.funding_stage || null,
        linkedin_activity: lead.linkedin_activity || null,
        review_status: reviewStatus,
        routing_destination: routingDestination
      }
    };
  });

  return processedItems;

} catch (err) {
  return [{ 
    json: { 
      error: "JSON Parsing Failed", 
      details: err.message,
      extracted_text: rawText 
    } 
  }];
}
